   75 ISTART = IDIV
C THE STARTING POINT OF A SUBCYCLE IS DIVISIBLE ONLY BY IDIV
C AND MUST NOT APPEAR IN ANY OTHER SUBCYCLE.
   80 MMIST = M - ISTART
      IF (ISTART.EQ.IDIV) GO TO 120
